parameters.text:
=Convierte este paquete factual en una pieza maestra de contenido para ARCANUM. Usa solamente los hechos entregados. Devuelve JSON valido, sin markdown. Escribe espanol correcto, incluidas todas las tildes. Cada campo debe aportar algo distinto: no repitas frases ni reformules la misma idea. Una enumeracion de funciones puede aparecer una sola vez en toda la pieza; si el script las enumera, reparte una idea distinta por tarjeta y no vuelvas a enumerarlas en caption. Nombra el producto como app, aplicacion o instrumento; nunca como paginas, volumen, capitulos ni libro. Evita tautologias, solemnidad artificial y relleno arcaizante. No uses calificadores como preciso, estructurado, riguroso, profundo, metodico o fundamental salvo que aparezcan literalmente en los hechos. El hook debe plantear una tension concreta. carousel debe contener entre 3 y 6 textos no vacios. El CTA debe tener entre 3 y 10 palabras e invitar a una funcion confirmada. source_ids solo puede contener identificadores presentes en sources. Si asset es null, alt_text debe ser una cadena vacia porque la imagen aun no existe.

PAQUETE FACTUAL:
{{ JSON.stringify($json) }}

FORMATO DE SALIDA:
{"hook":"","script":"","carousel":[],"caption":"","cta":"","alt_text":"","source_ids":[],"compliance":{"claims_supported":true,"warnings_applied":true}}

parameters.jsCode:
const incoming = $input.first().json;
let value = incoming.text ?? incoming.output ?? incoming;
if (value && typeof value === 'object' && value.output && typeof value.output === 'object') value = value.output;
return [{ json: { text: typeof value === 'string' ? value : JSON.stringify(value) } }];

const raw = $input.first().json.text;
const brief = $('Preparar paquete factual').first().json;
if (typeof raw !== 'string' || !raw.trim()) throw new Error('Gemini no devolvio texto.');
const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let draft;
try { draft = JSON.parse(cleaned); } catch (error) { throw new Error(`JSON editorial invalido: ${error.message}`); }
const errors = [];
const warnings = [];
const requiredText = ['hook', 'script', 'caption', 'cta', 'alt_text'];
for (const field of requiredText) {
  if (typeof draft[field] !== 'string') errors.push(`${field}: debe ser texto`);
}
if (typeof draft.hook === 'string' && (draft.hook.trim().length < 20 || draft.hook.length > 120)) errors.push('hook: longitud fuera de 20-120 caracteres');
if (typeof draft.script === 'string' && (draft.script.trim().length < 100 || draft.script.length > 700)) errors.push('script: longitud fuera de 100-700 caracteres');
if (!Array.isArray(draft.carousel) || draft.carousel.length < 3 || draft.carousel.length > 6 || draft.carousel.some((item) => typeof item !== 'string' || !item.trim())) errors.push('carousel: requiere 3-6 textos no vacios');
const ctaWords = typeof draft.cta === 'string' ? draft.cta.trim().split(/\s+/).filter(Boolean).length : 0;
if (ctaWords < 3 || ctaWords > 10) errors.push('cta: requiere 3-10 palabras');
if (typeof draft.cta === 'string' && /(conoce las funciones|disponibles en la aplicacion|descubre mas)/i.test(draft.cta.normalize('NFD').replace(/[\u0300-\u036f]/g, ''))) errors.push('cta: formula generica');
if (!brief.asset && typeof draft.alt_text === 'string' && draft.alt_text.trim()) errors.push('alt_text: debe quedar vacio hasta elegir un recurso visual');
const knownSources = new Set((brief.sources || []).map((source) => source.id));
if (!Array.isArray(draft.source_ids) || !draft.source_ids.length) errors.push('source_ids: falta trazabilidad');
else if (draft.source_ids.some((sourceId) => !knownSources.has(sourceId))) errors.push('source_ids: contiene una fuente no entregada');
if (draft.compliance?.claims_supported !== true) errors.push('compliance.claims_supported: debe ser true');
if (draft.compliance?.warnings_applied !== true) errors.push('compliance.warnings_applied: debe ser true');
const stopWords = new Set(['para','como','esta','este','esto','desde','entre','sobre','cada','solo','sino','tambien','traves','aplicacion']);
const tokens = (value) => new Set(String(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter((word) => word.length > 3 && !stopWords.has(word)));
const fragments = [
  ['hook', draft.hook], ['script', draft.script], ['caption', draft.caption], ['cta', draft.cta],
  ...(Array.isArray(draft.carousel) ? draft.carousel.map((item, index) => [`carousel[${index}]`, item]) : [])
].filter(([, value]) => typeof value === 'string' && value.trim());
for (let i = 0; i < fragments.length; i++) {
  for (let j = i + 1; j < fragments.length; j++) {
    const left = tokens(fragments[i][1]);
    const right = tokens(fragments[j][1]);
    const smaller = Math.min(left.size, right.size);
    if (smaller < 5) continue;
    const overlap = [...left].filter((token) => right.has(token)).length / smaller;
    if (overlap >= 0.72) errors.push(`repeticion alta: ${fragments[i][0]} y ${fragments[j][0]}`);
  }
}
const uniqueErrors = [...new Set(errors)];
return [{ json: { external_key: brief.external_key, status: uniqueErrors.length ? 'needs_revision' : 'ready_for_review', draft, validation: { valid: uniqueErrors.length === 0, score: Math.max(0, 100 - uniqueErrors.length * 15 - warnings.length * 5), errors: uniqueErrors, warnings } } }];

const item = $input.first().json;
const draft = item.draft || {};
const corpus = [draft.hook, draft.script, draft.caption, draft.cta, ...(Array.isArray(draft.carousel) ? draft.carousel : [])].filter(Boolean).join(' ');
const missingAccents = /\b(reflexion|proposito|comprension|tecnica|observacion|metodica|adivinacion|aplicacion|prediccion|simbolica|astrologia)\b/i;
if (missingAccents.test(corpus)) {
  item.validation.warnings = [...new Set([...(item.validation.warnings || []), 'ortografia: revisar tildes frecuentes'])];
  item.validation.score = Math.max(0, item.validation.score - 5);
}
return [{ json: item }];

const item = $input.first().json;
const brief = $('Preparar paquete factual').first().json;
const draft = item.draft || {};
const textFields = [draft.hook, draft.script, draft.caption, draft.cta, ...(Array.isArray(draft.carousel) ? draft.carousel : [])].filter((value) => typeof value === 'string');
const corpus = textFields.join(' ');
const normalize = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const normalizedCorpus = normalize(corpus);
const factualCorpus = normalize([brief.premise, ...(brief.facts || []).map((fact) => fact.claim), ...(brief.warnings || [])].filter(Boolean).join(' '));
const errors = [];
const forbiddenMedium = /\b(estas paginas|sus paginas|cada apartado|capitulos?|volumen|libro)\b/i;
if (forbiddenMedium.test(normalizedCorpus)) errors.push('voz: la app se presenta como libro o paginas');
if (/\bmetodo metodico\b/i.test(normalizedCorpus)) errors.push('voz: tautologia "metodo metodico"');
if (/\b(artificio alguno|lo inescrutable)\b/i.test(normalizedCorpus)) errors.push('voz: grandilocuencia artificial');
const qualifiers = [
  ['preciso', /\bprecis[ao]s?\b/i, /\bprecis[ao]s?\b/i],
  ['estructurado', /\bestructurad[ao]s?\b/i, /\bestructurad[ao]s?\b/i],
  ['riguroso', /\briguros[ao]s?\b/i, /\briguros[ao]s?\b/i],
  ['profundo', /\bprofund[ao]s?\b/i, /\bprofund[ao]s?\b/i],
  ['metodico', /\bmetodic[ao]s?\b/i, /\bmetodic[ao]s?\b/i],
  ['fundamental', /\bfundamentales?\b/i, /\bfundamentales?\b/i]
];
for (const [name, usedPattern, factPattern] of qualifiers) {
  if (usedPattern.test(normalizedCorpus) && !factPattern.test(factualCorpus)) errors.push(`claim: calificador no respaldado: ${name}`);
}
const newErrors = [...new Set(errors)].filter((error) => !(item.validation.errors || []).includes(error));
item.validation.errors = [...new Set([...(item.validation.errors || []), ...newErrors])];
item.validation.valid = item.validation.errors.length === 0;
item.validation.score = Math.max(0, Number(item.validation.score ?? 100) - newErrors.length * 15);
item.status = item.validation.valid ? 'ready_for_review' : 'needs_revision';
return [{ json: item }];
